/**
 * Shapes of the per-attack frame data generated by
 * `npm run cli -- import frames` (source: wuwalab, used with permission; see
 * ADR 0047). Game data, so it lives in code modules: one generated
 * `frames.ts` per character folder plus `src/echoes/frames.ts`.
 *
 * All values are frames at 60 frames per second, measured from the start of
 * the ability.
 */

/** One hit: `[frame, commitFrame, energy, concerto]`. A hit whose commit frame
 * is at or before the point the character leaves still lands, even if its
 * own frame comes later (that is what makes swap cancels work). Energy and
 * concerto are the game's raw values (×100 of what the UI shows). */
export type FrameHit = [frame: number, commitFrame: number, energy: number, concerto: number];

export interface AttackFrames {
  /** wuwalab ability name the frames came from. Two of our attacks can share
   * one ability (a tap and a hold half); see `shared`. */
  ability: string;
  /** Length when the action plays out. */
  total: number;
  /** Earliest frame the character can cancel into another action. 0 means
   * unknown, not instant. */
  cancel?: number;
  /** Earliest frame the character can be swapped out. */
  noSwap?: number;
  /** World freeze (enemies and timers) as `[start, end]`. */
  timeStop?: [number, number];
  /** Character locked in place as `[start, end]`. Informational. */
  motionStop?: [number, number];
  cooldown?: number;
  /** Energy and concerto gained (or spent, when negative) on cast. */
  onCast?: { energy?: number; concerto?: number };
  hits: FrameHit[];
  /** Happens away from the field (a coordinated attack, a lingering zone):
   * takes no field time. */
  offField?: boolean;
  /** Our attack covers only part of `ability`. Consecutive actions of the
   * same character that share the ability count its time once. */
  shared?: boolean;
}

export interface FrameDataFile {
  /** Date the data was fetched (YYYY-MM-DD). */
  syncedAt: string;
  attacks: Record<string, AttackFrames>;
}

export const FRAMES_PER_SECOND = 60;
